item.command:
/usr/bin/bash -lc "python - <<'PY'
import json, pathlib
for path in ['evidence/native_run/native_evaluator_input.json','evidence/native_run/post_run_artifacts/aux_data.json','evidence/native_run/task_context.json','evidence/native_run/job.json','evidence/native_run/system_state/pre_run.json','evidence/native_run/system_state/post_run.json','evidence/native_run/trajectories/steps.json']:
    print('\\n###', path)
    data=json.load(open(path))
    if isinstance(data, dict):
        print('keys', list(data)[:50])
        for k,v in data.items():
            if isinstance(v,(str,int,float,bool)) or v is None:
                print(k, repr(v)[:200])
            else:
                print(k, type(v).__name__, ('len='+str(len(v)) if hasattr(v,'__len__') else ''))

    elif isinstance(data,list):
        print('list len',len(data),'first type',type(data[0]).__name__ if data else None)
PY"

